arguments.command:
mkdir -p tmp/profile && cat > tmp/profile/group_timing.rb <<'EOF'
class GroupTiming
  RSpec::Core::Formatters.register self, :example_finished, :close

  def initialize(output)
    @output = output
    @by_group = Hash.new(0.0)
  end

  def example_finished(notification)
    group = notification.example.example_group.top_level? ? notification.example.example_group : notification.example.example_group.superclass
    @by_group[group.description + " " + group.metadata[:location].to_s] += notification.example.execution_result.run_time
  end

  def close(_notification)
    sorted = @by_group.sort_by { |_, v| -v }.first(40)
    sorted.each do |name, time|
      @output.puts format('%8.2fs  %s', time, name)
    end
    @output.puts "TOTAL example time: #{@by_group.values.sum.round(2)}s"
  end
end
EOF
echo done

