require 'benchmark'
redis = Rails.redis
redis.keys.each { |k| redis.del(k) }

n = 200
Benchmark.bm do |x|
  x.report('del(keys)') { n.times { redis.keys.each { |k| redis.del(k) }; redis.set('foo', 'bar') } }
  x.report('flushdb')   { n.times { redis.flushdb; redis.set('foo', 'bar') } }
  x.report('cache.clear') { n.times { Rails.cache.clear } }
  x.report('keys_no_del') { n.times { redis.keys } }
end
